style.css:
@-moz-document url("https://docs.google.com/document/") {
/* Background behind the page */
    body {
        background: #C3A995 !important; /* Muted beige tone */
    }

    /* Page container */
    .kix-appview-editor {
        background: rgba(255, 255, 255, 0.9) !important; /* Slightly transparent page */
        border-radius: 10px !important; /* Soft rounded edges */
        box-shadow: 5px 5px 15px rgba(0, 0, 0, 0.2) !important; /* Subtle drop shadow */
    }

    /* Text area (optional: change the default font) */
    .kix-wordhtmlgenerator-word-node {
        font-family: "Georgia", serif !important; /* Classy serif font */
        color: #4A3D35 !important; /* Soft brown text */
    }

    /* Toolbar & Menu bar */
    .docs-menubar, .kix-zoomdocumentplugin-zoomindicatordropdown {
        background: #A67B5B !important; /* Warm brown tone */
        color: #FFF !important;
    }

    /* Hide Google Docs blue buttons for a cleaner look */
    .docs-titlebar-buttons, .docs-explore-widget {
        display: none !important;
    }
}
